    # 100x100 RGB image with a red square in the center
    img = np.zeros((100, 100, 3), dtype=np.uint8)
    # Fill background with blue
    img[:] = [255, 0, 0]  # BGR
    # Draw red square
    cv2.rectangle(img, (25, 25), (75, 75), (0, 0, 255), -1)
