import axios from 'axios';

const apiClient = axios.create({
  baseURL: import.meta.env.VITE_API_BASE_URL || 'http://localhost:8000',
  headers: {
    'Content-Type': 'application/json',
  },
});

// Response interceptor for global error handling
apiClient.interceptors.response.use(
  (response) => response,
  (error) => {
    // Handle global errors like 401, 500, etc.
    const message = error.response?.data?.detail || error.message || 'An unexpected error occurred';
    console.error('[API Error]:', message);
    return Promise.reject(error);
  }
);

export default apiClient;

import { create } from 'zustand';

interface SessionState {
  currentProjectId: string | null;
  currentImage: string | null;
  status: 'idle' | 'running' | 'completed' | 'error';
  setProject: (id: string) => void;
  setImage: (path: string) => void;
  setStatus: (status: SessionState['status']) => void;
}

export const useSessionStore = create<SessionState>((set) => ({
  currentProjectId: null,
  currentImage: null,
  status: 'idle',
  setProject: (id) => set({ currentProjectId: id }),
  setImage: (path) => set({ currentImage: path }),
  setStatus: (status) => set({ status }),
}));

export interface ProjectConfig {
  training_path: string;
  object_reference_path?: string;
  logo_path?: string;
  color_correction: {
    reference_color_checker_path: string;
    project_specific_color_checker_path?: string;
  };
  geometrical_alignment: {
    reference_path?: string;
    marker_map: Record<string, number[][]>;
    output_size: [number, number];
  };
  masking: {
    drawing_layers: Record<string, string>;
  };
}

export interface AnalysisResult {
  success: bool;
  message: string;
  percentage: number;
  matched_pixels: number;
  total_pixels: number;
  image_path?: string;
  debug_paths: Record<string, string>;
}

export type SessionStatus = 'idle' | 'running' | 'completed' | 'error';

export interface Project {
  id: string;
  name: string;
  config: ProjectConfig;
}

export interface ProjectConfig {
  training_path: string;
  object_reference_path?: string;
  logo_path?: string;
  color_correction: {
    reference_color_checker_path: string;
    project_specific_color_checker_path?: string;
  };
  geometrical_alignment: {
    reference_path?: string;
    marker_map: Record<string, number[][]>;
    output_size: [number, number];
  };
  masking: {
    drawing_layers: Record<string, string>;
  };
}

export interface PipelineStep {
  id: string;
  name: string;
  status: 'pending' | 'processing' | 'completed' | 'failed';
  resultPath?: string;
}

export interface AnalysisSession {
  id: string;
  projectId: string;
  imagePath: string;
  status: SessionStatus;
  steps: PipelineStep[];
  startedAt: string;
  completedAt?: string;
}

export interface AnalysisResult {
  success: boolean;
  message: string;
  percentage: number;
  matched_pixels: number;
  total_pixels: number;
  image_path?: string;
  debug_paths: Record<string, string>;
}

export interface LogEntry {
  timestamp: string;
  level: 'info' | 'warn' | 'error' | 'debug';
  module: string;
  message: string;
}

import { http, HttpResponse } from 'msw';
import { Project, AnalysisSession } from '../../types';

const MOCK_PROJECTS: Project[] = [
  {
    id: 'proj-1',
    name: 'Benagol',
    config: {
      training_path: 'dataset/training_images',
      color_correction: { reference_color_checker_path: 'default_cc.png' },
      geometrical_alignment: { marker_map: {}, output_size: [1000, 1000] },
      masking: { drawing_layers: { '1': 'layer1.png' } }
    }
  }
];

export const handlers = [
  // List Projects
  http.get('*/projects', () => {
    return HttpResponse.json(MOCK_PROJECTS);
  }),

  // Start Analysis
  http.post('*/analysis/start', async ({ request }) => {
    const body = await request.json() as any;
    const session: AnalysisSession = {
      id: `session-${Math.random().toString(36).substr(2, 9)}`,
      projectId: body.projectId,
      imagePath: body.imagePath,
      status: 'running',
      startedAt: new Date().toISOString(),
      steps: [
        { id: 'cc', name: 'Color Correction', status: 'processing' },
        { id: 'align', name: 'Geometric Alignment', status: 'pending' },
      ]
    };
    return HttpResponse.json(session);
  }),

  // Get Logs
  http.get('*/logs', () => {
    return HttpResponse.json([
      { timestamp: new Date().toISOString(), level: 'info', module: 'core', message: 'Pipeline initialized.' },
      { timestamp: new Date().toISOString(), level: 'info', module: 'cc', message: 'Detecting color checker...' },
    ]);
  }),
];

import { setupWorker } from 'msw/browser';
import { handlers } from './handlers';

export const worker = setupWorker(...handlers);

