import React from 'react';
import { LogEntry } from '../types';

interface TerminalViewProps {
  logs: LogEntry[];
}

export const TerminalView: React.FC<TerminalViewProps> = ({ logs }) => {
  return (
    <div className="bg-black/80 rounded-lg p-4 font-mono text-sm border border-neutral-800 h-64 overflow-auto scrollbar-thin scrollbar-thumb-neutral-700">
      {logs.length === 0 && <span className="text-neutral-600 italic">Waiting for pipeline output...</span>}
      {logs.map((log, i) => (
        <div key={i} className="flex gap-3 mb-1 animate-in fade-in slide-in-from-left-1 duration-300">
          <span className="text-neutral-600">[{new Date(log.timestamp).toLocaleTimeString()}]</span>
          <span className={`font-bold ${log.level === 'error' ? 'text-red-500' : 'text-green-500'}`}>
            {log.module.toUpperCase()}
          </span>
          <span className="text-neutral-300">{log.message}</span>
        </div>
      ))}
    </div>
  );
};

import React from 'react';
import { Maximize2 } from 'lucide-react';

interface ViewportProps {
  title: string;
  imageUrl?: string;
  isLoading?: boolean;
}

export const Viewport: React.FC<ViewportProps> = ({ title, imageUrl, isLoading }) => {
  return (
    <div className="bg-neutral-900 border border-neutral-800 rounded-xl overflow-hidden flex flex-col group">
      <div className="px-4 py-2 border-b border-neutral-800 flex justify-between items-center bg-neutral-900/50">
        <span className="text-xs font-bold uppercase tracking-wider text-neutral-400">{title}</span>
        <button className="text-neutral-500 hover:text-white transition-colors">
          <Maximize2 className="w-3 h-3" />
        </button>
      </div>
      <div className="relative flex-1 min-h-[300px] bg-[radial-gradient(#262626_1px,transparent_1px)] [background-size:16px_16px] flex items-center justify-center">
        {isLoading ? (
          <div className="animate-pulse flex flex-col items-center gap-3">
            <div className="w-12 h-12 rounded-full border-2 border-green-600 border-t-transparent animate-spin" />
            <span className="text-xs text-neutral-500">Processing...</span>
