          <img src={imageUrl} alt={title} className="max-w-full max-h-full object-contain shadow-2xl" />
        ) : (
          <div className="text-neutral-700 flex flex-col items-center gap-2 italic">
            <span className="text-xs">No image available</span>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
